def run(url, focus, status, title, text, error, probe_status, probe_error):
    def clean(s, limit):
        if s is None:
            return ''
        return ' '.join(str(s).split())[:limit]

    u = clean(url, 300)
    f = clean(focus, 80)
    t = clean(title, 180)
    err = clean(error, 200)
    p_err = clean(probe_error, 200)
    st = status if status is not None else None
    pst = probe_status if probe_status is not None else None
    body = clean(text, 5000)

    facts = []
    if t:
        facts.append(f'Title: {t}')
    if st is not None:
        facts.append(f'Status: {st}')
    if pst is not None:
        facts.append(f'Probe status: {pst}')
    if body:
        parts = [p.strip() for p in body.split('\n') if p.strip()]
        for p in parts[:5]:
            facts.append(p[:400])
    if not facts and err:
        facts.append(f'Error: {err}')
    if not facts and p_err:
        facts.append(f'Probe error: {p_err}')
    if not facts:
        facts.append('No readable content was returned from the page.')

    availability = 'available' if st and int(st) >= 200 and int(st) < 400 and body else 'unavailable'
    error_summary = ''
    if availability == 'unavailable':
        if st is not None and int(st) >= 400:
            error_summary = f'HTTP status {int(st)}'
        elif err:
            error_summary = 'Request failed'
        elif p_err:
            error_summary = 'Probe failed'
        else:
            error_summary = 'No readable content'

    return {
        'url': u,
        'focus': f,
        'status': st,
        'title': t,
        'error': err,
        'probe_status': pst,
        'probe_error': p_err,
        'facts': facts,
        'facts_text': '\n'.join(f'- {x}' for x in facts),
        'availability': availability,
        'error_summary': error_summary
    }

def run(url, title, focus, status, probe_status, facts_text, availability, error_summary):
    def clean(s, limit):
        if s is None:
            return ''
        return ' '.join(str(s).split())[:limit]

    u = clean(url, 300)
    t = clean(title, 180) or 'the page'
    f = clean(focus, 80)
    facts = clean(facts_text, 5000)
    avail = clean(availability, 40)
    err = clean(error_summary, 120)

    if avail != 'available':
        speech = f'I could not read {t} because it is currently inaccessible. The page could not be summarized from the fetched content. Please try again later or use a different page.'
        report = f'''# Three-Sentence Web Summary

- **URL:** {u}
- **Title:** {t}
- **Status:** unavailable
- **Access issue:** {err or 'unavailable'}
- **Summary:** The page could not be read from the fetched content. No reliable three-sentence summary could be generated. Try again later or with a page that allows access.
'''
        return {'speech': speech[:700], 'report': report}

    focus_clause = f' with emphasis on {f}' if f else ''
    speech = f'{t} is a readable web page{focus_clause}. It appears to cover the main points listed in the fetched text. Here is the concise summary of those points.'
    report = f'''# Three-Sentence Web Summary

- **URL:** {u}
- **Title:** {t}
- **Status:** {status if status is not None else 'n/a'}
- **Probe status:** {probe_status if probe_status is not None else 'n/a'}

{facts}
'''
    return {'speech': speech[:700], 'report': report}
